INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(6684484, 1000099, 43191, '<td valign="top">There is a story going on in this one. The tones are wonderful, great lighting. I think it may be the guy''s back that brings this down a little for me. His stance feels very defensive like he doesn''t want us to be involved in this scene.I get a kind of  "blocked" feeling from this.</td>', 'There is a story going on in this one. The tones are wonderful, great lighting. I think it may be the guy''s back that brings this down a little for me. His stance feels very defensive like he doesn''t want us to be involved in this scene.I get a kind of  "blocked" feeling from this.', '2012-02-20 05:08:50.000000', NULL, 1),
(6684485, 1000048, 43191, '<td valign="top">It''s hard to make an ugly animal look good :P Aw shouldn''t call him ugly, just wrinkly, bobbly, droopy, hairy lol I dunno. I think he would have stood out more on a darker back ground.</td>', 'It''s hard to make an ugly animal look good :P Aw shouldn''t call him ugly, just wrinkly, bobbly, droopy, hairy lol I dunno. I think he would have stood out more on a darker back ground.', '2012-02-20 05:10:23.000000', NULL, 1),
(6684486, 1000081, 43191, '<td valign="top">Nice capture, bird is maybe a bit too shadowy. Love the reflection.</td>', 'Nice capture, bird is maybe a bit too shadowy. Love the reflection.', '2012-02-20 05:10:59.000000', NULL, 1),
(6684488, 999778, 43191, '<td valign="top">These guys are super cute. I think you need to either include the whole tail or crop right in close.</td>', 'These guys are super cute. I think you need to either include the whole tail or crop right in close.', '2012-02-20 05:11:44.000000', NULL, 1),
(6684489, 1000068, 43191, '<td valign="top">I like that they are all looking. I do think the busy back ground is rather distracting though.</td>', 'I like that they are all looking. I do think the busy back ground is rather distracting though.', '2012-02-20 05:12:26.000000', NULL, 1),
(6684490, 999170, 43191, '<td valign="top">The angle of this makes me feel a little dizzy. I like the minimalism of the two small birds facing each other.</td>', 'The angle of this makes me feel a little dizzy. I like the minimalism of the two small birds facing each other.', '2012-02-20 05:14:39.000000', NULL, 1),
