(6684607, 999927, 69368, '<td valign="top">unusual, but welld one!</td>', 'unusual, but welld one!', '2012-02-20 07:12:14.000000', NULL, 1),
(6684612, 999763, 93565, '<td valign="top">My first thought was that this was overprocessed, but I normally sorta dwell on the photos I vote on, and I like this a lot more now that I''ve looked at it a bit longer. For me, this sorta reminds me of the Japanese scrolls of the crashing waves and turbulent sea scenes with the stylized and extreme contrast branches being similar to the exaggerated edges of the waves. Interesting... almost looks like a negative image. A thoroughly appreciated 7 from me.</td>', 'My first thought was that this was overprocessed, but I normally sorta dwell on the photos I vote on, and I like this a lot more now that I''ve looked at it a bit longer. For me, this sorta reminds me of the Japanese scrolls of the crashing waves and turbulent sea scenes with the stylized and extreme contrast branches being similar to the exaggerated edges of the waves. Interesting... almost looks like a negative image. A thoroughly appreciated 7 from me.', '2012-02-20 07:15:44.000000', NULL, 1),
(6684613, 999775, 12611, '<td valign="top">i like it, even if it is about 50% border. fantastic use of what is <i> not</i> in the frame.</td>', 'i like it, even if it is about 50% border. fantastic use of what is  not in the frame.', '2012-02-20 07:15:49.000000', NULL, 1),
(6684615, 999172, 12611, '<td valign="top">great expression.</td>', 'great expression.', '2012-02-20 07:16:35.000000', NULL, 1),
(6684617, 999800, 93565, '<td valign="top">This really needs a reflector or a fill or some additional processing. Your title leads us to your pets eyes, which, for the viewer, are very dark and much of their detail being in the higher zones. We, as viewers, also do not have any knowledge of his typical behavior, so it''s a bit of a stretch for the viewer to follow what "that look" really means.</td>', 'This really needs a reflector or a fill or some additional processing. Your title leads us to your pets eyes, which, for the viewer, are very dark and much of their detail being in the higher zones. We, as viewers, also do not have any knowledge of his typical behavior, so it''s a bit of a stretch for the viewer to follow what "that look" really means.', '2012-02-20 07:18:01.000000', NULL, 1),
(6684619, 999819, 93565, '<td valign="top">Ah, another great seabird photo. I love the congregation of birds you''ve caught here, and as I said on another seabird shot, great job keeping the bird nicely sharp and including the ocean in a suitably detailed fashion to provide context. Very nice.</td>', 'Ah, another great seabird photo. I love the congregation of birds you''ve caught here, and as I said on another seabird shot, great job keeping the bird nicely sharp and including the ocean in a suitably detailed fashion to provide context. Very nice.', '2012-02-20 07:19:16.000000', NULL, 1),
