(6685850, 999627, 114285, '<td valign="top">Great shot, with nice motion blur, already voted.</td>', 'Great shot, with nice motion blur, already voted.', '2012-02-21 05:14:08.000000', NULL, 1),
(6685860, 999882, 136168, '<td valign="top">badass picture! :) 9</td>', 'badass picture! :) 9', '2012-02-21 06:05:41.000000', NULL, 1),
