INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(6685864, 1000050, 136168, '<td valign="top">absolutely love it! subject, tones and the composition are tops..minor quirk are the out of focus eyes but it doesn''t take away from how strong the image is</td>', 'absolutely love it! subject, tones and the composition are tops..minor quirk are the out of focus eyes but it doesn''t take away from how strong the image is', '2012-02-21 06:21:50.000000', NULL, 1),
(6685943, 1000074, 11854, '<td valign="top">My granddaughter watches this video from Gigglebellies that does a version of Old MacDonald had a farm, and in that version the cow is named Kissy moo. It''s pretty wild. LOL! Sorry for the random thought. I like the grin! 8</td>', 'My granddaughter watches this video from Gigglebellies that does a version of Old MacDonald had a farm, and in that version the cow is named Kissy moo. It''s pretty wild. LOL! Sorry for the random thought. I like the grin! 8', '2012-02-21 09:05:59.000000', NULL, 1),
(6685946, 1000085, 11854, '<td valign="top">OMG! I''m so glad that''s not a real duck! LOL!</td>', 'OMG! I''m so glad that''s not a real duck! LOL!', '2012-02-21 09:08:07.000000', NULL, 1),
(6685952, 999354, 65234, '<td valign="top">Sometimes it is not good to be a chicken.  Although the tilt in the neck indicates a bit of attitude.  I''m not sure I''d mess with her!  Like the bokeh in the back;  I think I''d crop a bit tighter on the right or darken it more to diminish the impact of that fan pattern there.</td>', 'Sometimes it is not good to be a chicken.  Although the tilt in the neck indicates a bit of attitude.  I''m not sure I''d mess with her!  Like the bokeh in the back;  I think I''d crop a bit tighter on the right or darken it more to diminish the impact of that fan pattern there.', '2012-02-21 09:27:04.000000', NULL, 1),
(6686040, 1000003, 54446, '<td valign="top">Technically excellent.</td>', 'Technically excellent.', '2012-02-21 11:11:19.000000', NULL, 1),
(6686044, 999900, 54446, '<td valign="top">Wonderful pet portrait.  It''s my top choice for a ribbon in this challenge.  I don''t do studio work with animals, but this is very well done.  10</td>', 'Wonderful pet portrait.  It''s my top choice for a ribbon in this challenge.  I don''t do studio work with animals, but this is very well done.  10', '2012-02-21 11:14:00.000000', NULL, 1),
(6686046, 999917, 54446, '<td valign="top">Just as cute as can be.  Superb job on the whites, exposure and contrast.  9</td>', 'Just as cute as can be.  Superb job on the whites, exposure and contrast.  9', '2012-02-21 11:15:00.000000', NULL, 1),
(6686055, 999775, 54446, '<td valign="top">I sure have mixed reactions to this image.  Love the zebra stripes abstract part.  I hate the long black bars top and bottom.  And, there is no eye catch glint, which is a big deficit in any animal image for me.  I did give this a "7".  Would have scored this much higher if you had showed more of the animal.</td>', 'I sure have mixed reactions to this image.  Love the zebra stripes abstract part.  I hate the long black bars top and bottom.  And, there is no eye catch glint, which is a big deficit in any animal image for me.  I did give this a "7".  Would have scored this much higher if you had showed more of the animal.', '2012-02-21 11:19:10.000000', NULL, 1),
(6686061, 1000068, 54446, '<td valign="top">Wonderful black-tailed deer herd.  You have the attention of the muleys.  It''s a very pleasing nature scene to me.  10</td>', 'Wonderful black-tailed deer herd.  You have the attention of the muleys.  It''s a very pleasing nature scene to me.  10', '2012-02-21 11:22:00.000000', NULL, 1),
(6686078, 999819, 54446, '<td valign="top">Excellent job on capturing the action.  Love your use of narrow DOF, selective focus.  9</td>', 'Excellent job on capturing the action.  Love your use of narrow DOF, selective focus.  9', '2012-02-21 12:02:46.000000', NULL, 1),
