(6691011, 1000081, 143245, '<td valign="top">Nice reflection on the water</td>', 'Nice reflection on the water', '2012-02-24 14:48:02.000000', NULL, 1),
(6691058, 1000052, 6804, '<td valign="top">This is my favorite entry of the challenge.  This is some amazing and inspirational work!  The soft reflections in the water add a calm feeling to the overall image.  The photo is full of mid-tones which is so rare anymore.  The subject is not being limited in the frame by a rule of thirds or some other general composition rule.  To me this image is a very confident style. It is bold to break the rules of composition.  This one is perfect!  I hope to see it on the front page when the challenge closes.</td>', 'This is my favorite entry of the challenge.  This is some amazing and inspirational work!  The soft reflections in the water add a calm feeling to the overall image.  The photo is full of mid-tones which is so rare anymore.  The subject is not being limited in the frame by a rule of thirds or some other general composition rule.  To me this image is a very confident style. It is bold to break the rules of composition.  This one is perfect!  I hope to see it on the front page when the challenge closes.', '2012-02-24 15:31:03.000000', NULL, 1),
(6691063, 999603, 6804, '<td valign="top">Wow!  This is great work!  Sharp in the right places, perfectly soft over-all.  The subject is a rare find which brings additional interest to the image.  It''s hard enough to find such a willing subject, let alone to have one actually pose for you so gracefully.  Kudos on one of my favorite entries in this challenge.  Awesome work!</td>', 'Wow!  This is great work!  Sharp in the right places, perfectly soft over-all.  The subject is a rare find which brings additional interest to the image.  It''s hard enough to find such a willing subject, let alone to have one actually pose for you so gracefully.  Kudos on one of my favorite entries in this challenge.  Awesome work!', '2012-02-24 15:36:53.000000', NULL, 1),
(6691076, 1000067, 6804, '<td valign="top">This has some great potential, but it is quite flat for my taste.  I think splitting the image to red or green and boosting the gamma would help this pop a little.  I hope that is helpful to you....   good luck in the challenge!</td>', 'This has some great potential, but it is quite flat for my taste.  I think splitting the image to red or green and boosting the gamma would help this pop a little.  I hope that is helpful to you....   good luck in the challenge!', '2012-02-24 15:45:53.000000', NULL, 1),
(6691094, 1000050, 6804, '<td valign="top">This just makes me laugh!  It''s a great shot.  I''m ok with the sepia in a black/white challenge, but I do think it might cost you some points with some of the voters. If I were to really nit-pick; The sharp focus is on the teeth and it falls just a little soft in the eyes for me. My preference would be to have the eyes sharp.  The background is perfect!  A 9 from me!  Good luck in the challenge!</td>', 'This just makes me laugh!  It''s a great shot.  I''m ok with the sepia in a black/white challenge, but I do think it might cost you some points with some of the voters. If I were to really nit-pick; The sharp focus is on the teeth and it falls just a little soft in the eyes for me. My preference would be to have the eyes sharp.  The background is perfect!  A 9 from me!  Good luck in the challenge!', '2012-02-24 15:51:10.000000', NULL, 1),
(6691100, 999952, 6804, '<td valign="top">Hehehe.... the things our pets must endure when we have our camera in hand.  Very nice work!</td>', 'Hehehe.... the things our pets must endure when we have our camera in hand.  Very nice work!', '2012-02-24 15:53:42.000000', NULL, 1),
