(6691316, 999565, 138630, '<td valign="top">The sidelight is handled perfectly and the focus is excellent.  What a nice, alert pose you got for this beautiful portrait.</td>', 'The sidelight is handled perfectly and the focus is excellent.  What a nice, alert pose you got for this beautiful portrait.', '2012-02-24 20:12:36.000000', NULL, 1),
(6691317, 999748, 138630, '<td valign="top">Looks as if they are dancing on his back -- great sense of movement here without the motion blur I might expect.  Nice that the birds were against the dark trees -- sets them off so well.  Lovely capture.</td>', 'Looks as if they are dancing on his back -- great sense of movement here without the motion blur I might expect.  Nice that the birds were against the dark trees -- sets them off so well.  Lovely capture.', '2012-02-24 20:14:07.000000', NULL, 1),
