(6692510, 1000087, 114225, '<td valign="top">Nicely done. You made sure to setup context with this photo which really helps it stand out.</td>', 'Nicely done. You made sure to setup context with this photo which really helps it stand out.', '2012-02-26 15:29:45.000000', NULL, 1),
(6692512, 999603, 114225, '<td valign="top">Wonderful use of contrast in this photo.</td>', 'Wonderful use of contrast in this photo.', '2012-02-26 15:30:26.000000', NULL, 1),
(6692514, 999900, 114225, '<td valign="top">This is a gorgeous portrait. Great expression, details, and eyes.</td>', 'This is a gorgeous portrait. Great expression, details, and eyes.', '2012-02-26 15:31:23.000000', NULL, 1),
(6692515, 999748, 114225, '<td valign="top">Nicely done. One of the more unique shots in this challenge.</td>', 'Nicely done. One of the more unique shots in this challenge.', '2012-02-26 15:31:50.000000', NULL, 1),
(6692517, 999762, 114225, '<td valign="top">Haha, great job getting up close and personal.</td>', 'Haha, great job getting up close and personal.', '2012-02-26 15:32:16.000000', NULL, 1),
(6692518, 999933, 114225, '<td valign="top">Ah, the rare black rhino. I was lucky enough to see two of these on my trip to Africa. An amazing, and frightening creature.</td>', 'Ah, the rare black rhino. I was lucky enough to see two of these on my trip to Africa. An amazing, and frightening creature.', '2012-02-26 15:33:21.000000', NULL, 1),
(6692519, 999764, 114225, '<td valign="top">The snow on the back/head is wonderful.</td>', 'The snow on the back/head is wonderful.', '2012-02-26 15:33:56.000000', NULL, 1),
(6692521, 1000097, 114225, '<td valign="top">Haha, what a fun photo op this is.</td>', 'Haha, what a fun photo op this is.', '2012-02-26 15:34:37.000000', NULL, 1),
(6692522, 999744, 114225, '<td valign="top">I like the framing you used here. And the pun in the title is exquisite.</td>', 'I like the framing you used here. And the pun in the title is exquisite.', '2012-02-26 15:35:14.000000', NULL, 1),
(6692523, 999952, 114225, '<td valign="top">Hahaha, I can''t believe you got it to cooperate. One of the better pet portraits of this challenge.</td>', 'Hahaha, I can''t believe you got it to cooperate. One of the better pet portraits of this challenge.', '2012-02-26 15:35:53.000000', NULL, 1),
(6692525, 999208, 114225, '<td valign="top">In B&amp;W it''s amazing how this bright bird can hide.</td>', 'In B&W it''s amazing how this bright bird can hide.', '2012-02-26 15:36:59.000000', NULL, 1),
(6692526, 1000034, 114225, '<td valign="top">Cool. Not many aquatic animals in this challenge, and this one is really well done.</td>', 'Cool. Not many aquatic animals in this challenge, and this one is really well done.', '2012-02-26 15:37:30.000000', NULL, 1),
(6692527, 999726, 114225, '<td valign="top">Very nice. I like how his fur looks so soft.</td>', 'Very nice. I like how his fur looks so soft.', '2012-02-26 15:38:09.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(6692529, 999437, 114225, '<td valign="top">Wonderful job with the details and contrast.</td>', 'Wonderful job with the details and contrast.', '2012-02-26 15:38:38.000000', NULL, 1),
(6692530, 999801, 114225, '<td valign="top">Very nicely done. The falling snow adds a lot to this image.</td>', 'Very nicely done. The falling snow adds a lot to this image.', '2012-02-26 15:39:29.000000', NULL, 1),
(6692531, 999851, 138721, '<td valign="top">impressive !</td>', 'impressive !', '2012-02-26 15:39:47.000000', NULL, 1),
(6692538, 999762, 138630, '<td valign="top">Terrific pov and a favorite though I would like to see whiter whites and blacker blacks plus a lightening in the area of the eyes if you could do that convincingly.</td>', 'Terrific pov and a favorite though I would like to see whiter whites and blacker blacks plus a lightening in the area of the eyes if you could do that convincingly.', '2012-02-26 16:38:14.000000', NULL, 1),
(6692539, 1000085, 138630, '<td valign="top">Wonderful action shot - love the dripping water and the look of his wet coat.  Glad he was just practicing on a decoy :)</td>', 'Wonderful action shot - love the dripping water and the look of his wet coat.  Glad he was just practicing on a decoy :)', '2012-02-26 16:39:19.000000', NULL, 1),
(6692540, 999414, 138630, '<td valign="top">I''ve been bumping this steadily all week -- I love the white on white and the lines of the composition.  That outstretched leg is great.  I would take out the black speck near the right edge about level with the paw.</td>', 'I''ve been bumping this steadily all week -- I love the white on white and the lines of the composition.  That outstretched leg is great.  I would take out the black speck near the right edge about level with the paw.', '2012-02-26 16:40:32.000000', NULL, 1),
(6692541, 999624, 138630, '<td valign="top">Nice detail and light and a regal near profile pose -- I like that I can see both eyes.</td>', 'Nice detail and light and a regal near profile pose -- I like that I can see both eyes.', '2012-02-26 16:41:09.000000', NULL, 1),
(6692544, 998725, 138630, '<td valign="top">Probably my favorite cat entry and one of my favorite pets entries -- I did not go into the voting consciously biased for other-than-pets shots, but I noticed after I finished that I apparently was.  This is just a lovely portrait of a beautiful cat, though -- I think I would like to be able to make out a bit of the body so the head didn''t appear to be floating quite so much.</td>', 'Probably my favorite cat entry and one of my favorite pets entries -- I did not go into the voting consciously biased for other-than-pets shots, but I noticed after I finished that I apparently was.  This is just a lovely portrait of a beautiful cat, though -- I think I would like to be able to make out a bit of the body so the head didn''t appear to be floating quite so much.', '2012-02-26 16:44:00.000000', NULL, 1),
(6692545, 1000068, 138630, '<td valign="top">What''s with the two on the right who could give a hoot?  Very nice composition - the placement and lines of the tree are particularly nice.  Wouldn''t it be great if the fence wasn''t there -- though it isn''t that obtrusive.  Good score from me.</td>', 'What''s with the two on the right who could give a hoot?  Very nice composition - the placement and lines of the tree are particularly nice.  Wouldn''t it be great if the fence wasn''t there -- though it isn''t that obtrusive.  Good score from me.', '2012-02-26 16:46:53.000000', NULL, 1),
(6692553, 999819, 12611, '<td valign="top">lost in the patterns and rhythms... beautiful eye and processing.</td>', 'lost in the patterns and rhythms... beautiful eye and processing.', '2012-02-26 17:29:10.000000', NULL, 1),
(6692582, 999900, 140771, '<td valign="top">Beautiful!  The clarity, lighting, eyes - very well done.</td>', 'Beautiful!  The clarity, lighting, eyes - very well done.', '2012-02-26 18:38:56.000000', NULL, 1),
